import prismaMock from '../prisma-mock';
import {
  deleteComment,
  favoriteArticle,
  unfavoriteArticle,
  updateComment,
} from '../../app/routes/article/article.service';

describe('ArticleService', () => {
  describe('deleteComment', () => {
    test('should throw an error ', () => {
      // Given
      const id = 123;
      const idUser = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      expect(deleteComment(id, idUser)).rejects.toThrowError();
    });
  });

  describe('favoriteArticle', () => {
    test('should return the favorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      // @ts-ignore
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(favoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(favoriteArticle(slug, id)).rejects.toThrowError();
    });
  });
  describe('unfavoriteArticle', () => {
    test('should return the unfavorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(unfavoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(unfavoriteArticle(slug, id)).rejects.toThrowError();
    });
  });

  describe('updateComment', () => {
    const slug = 'How-to-train-your-dragon';
    const commentId = 123;
    const ownerId = 456;

    test('should reject a blank body with 422 and not query the database', async () => {
      // Then
      await expect(updateComment('', slug, commentId, ownerId)).rejects.toMatchObject({
        errorCode: 422,
      });
      expect(prismaMock.comment.findFirst).not.toHaveBeenCalled();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw 404 if the comment is not found on the article', async () => {
      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(updateComment('new body', slug, commentId, ownerId)).rejects.toMatchObject({
        errorCode: 404,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw 403 if the user is not the author of the comment', async () => {
      // Given
      const otherUserId = 789;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ author: { id: ownerId } });

      // Then
      await expect(updateComment('new body', slug, commentId, otherUserId)).rejects.toMatchObject({
        errorCode: 403,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should update the body, set updatedAt and return the comment', async () => {
      // Given
      const newBody = 'edited body';
      const createdAt = new Date('2026-10-01T10:00:00Z');
      const editedAt = new Date('2026-10-02T10:00:00Z');

      const mockedUpdatedComment = {
        id: commentId,
        createdAt,
        updatedAt: editedAt,
        body: newBody,
        authorId: ownerId,
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ author: { id: ownerId } });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment);

      // Then
      await expect(updateComment(newBody, slug, commentId, ownerId)).resolves.toEqual({
        id: commentId,
        createdAt,
        updatedAt: editedAt,
        body: newBody,
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          following: false,
        },
      });

      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: expect.objectContaining({ body: newBody, updatedAt: expect.any(Date) }),
        }),
      );
    });
  });
});

