} from '../../app/routes/article/article.service';

describe('ArticleService', () => {
  describe('deleteComment', () => {
    test('should throw an error ', () => {
      // Given
      const id = 123;
      const idUser = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      expect(deleteComment(id, idUser)).rejects.toThrowError();
    });

    test('should soft delete the comment by setting deletedAt and keep the row', async () => {
      // Given
      const commentId = 123;
      const ownerId = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({
        author: { id: ownerId, username: 'RealWorld' },
      });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue({});

      // Then
      await expect(deleteComment(commentId, ownerId)).resolves.toBeUndefined();
      expect(prismaMock.comment.update).toHaveBeenCalledWith({
        where: { id: commentId },
        data: { deletedAt: expect.any(Date) },
      });
      expect(prismaMock.comment.delete).not.toHaveBeenCalled();
    });

    test('should throw 404 for a comment that is missing or already deleted', async () => {
      // Given
      const commentId = 123;
      const userId = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(deleteComment(commentId, userId)).rejects.toMatchObject({ errorCode: 404 });
      await expect(deleteComment(commentId, userId)).rejects.toHaveProperty('message', {
        errors: { comment: ['not found'] },
      });
      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ id: commentId, deletedAt: null }),
        }),
      );
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });
  });

  describe('getCommentsByArticle', () => {
    const slug = 'How-to-train-your-dragon';

    test('should leave deleted comments out of the query and keep the other filters', async () => {
      // Given
      const userId = 456;

      // When
      // @ts-ignore
      prismaMock.article.findUnique.mockResolvedValue({ comments: [] });

      // Then
      await getCommentsByArticle(slug, userId);
      expect(prismaMock.article.findUnique).toHaveBeenCalledWith(
        expect.objectContaining({
          include: {
            comments: expect.objectContaining({
              where: {
                OR: [{ author: { demo: true } }, { author: { id: userId } }],
                deletedAt: null,
              },
            }),
          },
        }),
      );
    });

    test('should return the remaining comments with the author mapped', async () => {
      // Given
      const createdAt = new Date('2026-10-01T10:00:00Z');
      const updatedAt = new Date('2026-10-01T10:00:00Z');

      // When
      // @ts-ignore
      prismaMock.article.findUnique.mockResolvedValue({
        comments: [
          {
            id: 1,
            createdAt,
            updatedAt,
            body: 'still here',
            author: { username: 'RealWorld', bio: null, image: null, followedBy: [] },
          },
        ],
      });

      // Then
      await expect(getCommentsByArticle(slug)).resolves.toEqual([
        {
          id: 1,
          createdAt,
          updatedAt,
          body: 'still here',
          author: { username: 'RealWorld', bio: null, image: null, following: false },
        },
      ]);
    });
  });

