  });

  describe('updateComment', () => {
    const slug = 'How-to-train-your-dragon';
    const commentId = 123;
    const ownerId = 456;

    test('should reject a blank body with 422 and not query the database', async () => {
      // Then
      await expect(updateComment('', slug, commentId, ownerId)).rejects.toMatchObject({
        errorCode: 422,
      });
      expect(prismaMock.comment.findFirst).not.toHaveBeenCalled();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw 404 if the comment is not found on the article', async () => {
      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(updateComment('new body', slug, commentId, ownerId)).rejects.toMatchObject({
        errorCode: 404,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw 403 if the user is not the author of the comment', async () => {
      // Given
      const otherUserId = 789;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ author: { id: ownerId } });

      // Then
      await expect(updateComment('new body', slug, commentId, otherUserId)).rejects.toMatchObject({
        errorCode: 403,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should update the body, set updatedAt and return the comment', async () => {
      // Given
      const newBody = 'edited body';
      const createdAt = new Date('2026-10-01T10:00:00Z');
      const editedAt = new Date('2026-10-02T10:00:00Z');

      const mockedUpdatedComment = {
        id: commentId,
        createdAt,
        updatedAt: editedAt,
        body: newBody,
        authorId: ownerId,
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ author: { id: ownerId } });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment);

      // Then
      await expect(updateComment(newBody, slug, commentId, ownerId)).resolves.toEqual({
        id: commentId,
        createdAt,
        updatedAt: editedAt,
        body: newBody,
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          following: false,
        },
      });

      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: expect.objectContaining({ body: newBody, updatedAt: expect.any(Date) }),
        }),
      );
    });
  });
});

